INSERT INTO games (slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured) VALUES
('minecraft', 'Minecraft', 'Build anything you can imagine in the world''s most popular sandbox game.', 'Minecraft is a sandbox game of infinite creativity. Mine blocks, craft tools, build towering structures, and survive against monsters in a procedurally generated world of endless possibility. Play solo, join friends online, or explore countless community-made worlds and mods — there is truly something for everyone in this modern classic.', 'Mojang Studios', 'Mojang Studios', '2011-11-18', ARRAY['Sandbox','Survival','Adventure'], ARRAY['Crafting','Open World','Multiplayer','Creative','Block-Based'], ARRAY['Single-player','Online Co-op','Local Co-op','Cross-Platform Play','Controller Support','Cloud Saves'], 'https://upload.wikimedia.org/wikipedia/commons/8/84/Minecraft_Logo_%28higher_quality%29.png', 'https://upload.wikimedia.org/wikipedia/commons/8/84/Minecraft_Logo_%28higher_quality%29.png', 93, '$26.99', true),
('grand-theft-auto-v', 'Grand Theft Auto V', 'A sprawling satirical open world of crime and opportunity in Los Santos.', 'Follow three very different criminals — a retired bank robber, a street hustler, and a psychotic lunatic — through the sun-soaked city of Los Santos. With a massive open world, razor-sharp satire, endless activities, and the ever-popular GTA Online, GTA V remains one of the most played games ever made.', 'Rockstar North', 'Rockstar Games', '2013-09-17', ARRAY['Action','Adventure'], ARRAY['Open World','Crime','Third-Person','Multiplayer','Satire'], ARRAY['Single-player','Online PvP','Online Co-op','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/a/a5/Grand_Theft_Auto_V.png', 'https://upload.wikimedia.org/wikipedia/en/a/a5/Grand_Theft_Auto_V.png', 96, '$29.99', true),
('the-witcher-3-wild-hunt', 'The Witcher 3: Wild Hunt', 'A story-driven RPG of monster hunting and moral ambiguity.', 'You are Geralt of Rivia, a monster slayer for hire, on a quest to find your adopted daughter in a war-torn world. With rich characters, meaningful choices, breathtaking landscapes, and two massive story expansions, The Witcher 3 set a new standard for open-world RPGs and remains a genre benchmark.', 'CD Projekt Red', 'CD Projekt', '2015-05-19', ARRAY['RPG','Adventure','Action'], ARRAY['Open World','Story Rich','Choices Matter','Fantasy','Third-Person'], ARRAY['Single-player','Controller Support','Achievements','Cloud Saves'], 'https://upload.wikimedia.org/wikipedia/en/0/0c/Witcher_3_cover_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/0/0c/Witcher_3_cover_art.jpg', 93, '$49.99', true),
('god-of-war-ragnarok', 'God of War Ragnarök', 'Kratos and Atreus journey through the Nine Realms as the end times approach.', 'The epic conclusion to the Norse saga. Father and son face the oncoming Ragnarök, traveling through breathtaking realms, battling gods and monsters, and grappling with what it means to be a father, a son, and a warrior. Combat is visceral, the storytelling is superb, and the visuals are stunning.', 'Santa Monica Studio', 'Sony Interactive Entertainment', '2022-11-09', ARRAY['Action','Adventure','RPG'], ARRAY['Mythology','Story Rich','Third-Person','Single-player','Beautiful'], ARRAY['Single-player','Controller Support','Achievements','Photo Mode'], 'https://upload.wikimedia.org/wikipedia/en/e/ee/God_of_War_Ragnar%C3%B6k_cover.jpg', 'https://upload.wikimedia.org/wikipedia/en/e/ee/God_of_War_Ragnar%C3%B6k_cover.jpg', 94, '$59.99', true),
('the-last-of-us-part-i', 'The Last of Us Part I', 'A heartbreaking post-apocalyptic journey of survival and love.', 'Joel, a hardened survivor, is hired to smuggle 14-year-old Ellie out of a quarantine zone. What starts as a simple job becomes a brutal journey across a decimated America. With masterful storytelling, tense survival gameplay, and unforgettable characters, The Last of Us is one of gaming''s greatest narratives.', 'Naughty Dog', 'Sony Interactive Entertainment', '2022-09-02', ARRAY['Action','Adventure','Horror'], ARRAY['Story Rich','Post-apocalyptic','Single-player','Third-Person','Emotional'], ARRAY['Single-player','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/8/86/The_Last_of_Us_Part_I_cover.jpg', 'https://upload.wikimedia.org/wikipedia/en/8/86/The_Last_of_Us_Part_I_cover.jpg', 88, '$49.99', true),
('sekiro-shadows-die-twice', 'Sekiro: Shadows Die Twice', 'Hardened ninja combat in a beautifully brutal Sengoku-era Japan.', 'You are a shinobi bound to protect a young lord of an ancient bloodline, facing impossible odds. With precise, rhythm-based sword combat, a rich world of myth and stealth, and some of FromSoftware''s most demanding boss fights, Sekiro rewards mastery like few other games.', 'FromSoftware', 'Activision', '2019-03-22', ARRAY['Action','Adventure'], ARRAY['Souls-like','Difficult','Stealth','Historical','Single-player'], ARRAY['Single-player','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/6/6e/Sekiro_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/6/6e/Sekiro_art.jpg', 90, '$59.99', false),
('doom-eternal', 'DOOM Eternal', 'Rip and tear through hell in the most aggressive shooter ever made.', 'The legions of Hell have invaded Earth. As the Doom Slayer, you are the only thing standing between humanity and extinction. Chain together glory kills, devastating weapons, and relentless movement in a power-fantasy shooter that never lets up.', 'id Software', 'Bethesda Softworks', '2020-03-20', ARRAY['Shooter','Action'], ARRAY['FPS','Fast-Paced','Single-player','Metal','Difficult'], ARRAY['Single-player','Online PvP','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/9/9d/Cover_Art_of_Doom_Eternal.png', 'https://upload.wikimedia.org/wikipedia/en/9/9d/Cover_Art_of_Doom_Eternal.png', 90, '$29.99', false),
('animal-crossing-new-horizons', 'Animal Crossing: New Horizons', 'Escape to a peaceful island paradise you can shape as you like.', 'Build your own island getaway, meet charming animal villagers, catch bugs and fish, decorate your home, and live life at your own pace. A gentle, ever-changing world that rewards daily visits and creativity — the ultimate cozy game.', 'Nintendo EPD', 'Nintendo', '2020-03-20', ARRAY['Simulation','Adventure'], ARRAY['Cozy','Life Sim','Crafting','Relaxing','Multiplayer'], ARRAY['Single-player','Local Co-op','Online Co-op','Controller Support'], 'https://upload.wikimedia.org/wikipedia/en/1/1f/Animal_Crossing_New_Horizons.jpg', 'https://upload.wikimedia.org/wikipedia/en/1/1f/Animal_Crossing_New_Horizons.jpg', 90, '$59.99', false),
('ea-sports-fc-24', 'EA Sports FC 24', 'The world''s game, with millions of players and the most realistic football yet.', 'Formerly FIFA, EA Sports FC 24 brings authentic football with real clubs, players, and leagues from around the world. With HyperMotionV technology, playing styles modeled on real pros, and modes like Ultimate Team and Career, it''s the definitive football experience.', 'EA Vancouver', 'EA Sports', '2023-09-29', ARRAY['Sports','Simulation'], ARRAY['Football','Multiplayer','PvP','Licensed','Ultimate Team'], ARRAY['Single-player','Online PvP','Local Co-op','Controller Support','Cross-Platform Play'], 'https://upload.wikimedia.org/wikipedia/en/b/b3/EA_FC24_Cover.jpg', 'https://upload.wikimedia.org/wikipedia/en/b/b3/EA_FC24_Cover.jpg', 78, '$69.99', false),
('fortnite', 'Fortnite', 'The cultural phenomenon battle royale with endless crossovers and modes.', 'Drop in, gear up, and be the last one standing in this massively popular battle royale. With constant content updates, wild collaborations, creative mode, and a vibrant, cartoonish style, Fortnite is free-to-play fun that has become a global social hangout.', 'Epic Games', 'Epic Games', '2017-07-25', ARRAY['Shooter','Action','Free to Play'], ARRAY['Battle Royale','Multiplayer','PvP','Building','Team-Based'], ARRAY['Online PvP','Cross-Platform Play','Voice Chat','Controller Support'], 'https://upload.wikimedia.org/wikipedia/commons/0/0e/FortniteLogo.svg', 'https://upload.wikimedia.org/wikipedia/commons/0/0e/FortniteLogo.svg', 80, 'Free', true),
('overwatch-2', 'Overwatch 2', 'A team-based hero shooter with a vibrant cast of unique heroes.', 'Team up and pick your hero from a diverse roster of tank, damage, and support characters, each with their own abilities and personality. With fast-paced objective-based matches and colorful, competitive action, Overwatch 2 is a polished, always-evolving hero shooter.', 'Blizzard Entertainment', 'Blizzard Entertainment', '2022-10-04', ARRAY['Shooter','Action','Free to Play'], ARRAY['Hero Shooter','Multiplayer','PvP','Team-Based','Competitive'], ARRAY['Online PvP','Cross-Platform Play','Voice Chat','Controller Support'], 'https://upload.wikimedia.org/wikipedia/en/8/89/Overwatch_2_Steam_artwork.jpg', 'https://upload.wikimedia.org/wikipedia/en/8/89/Overwatch_2_Steam_artwork.jpg', 79, 'Free', false),
('terraria', 'Terraria', 'Dig, fight, explore, build — a 2D sandbox adventure of endless depth.', 'In Terraria, the world is your canvas and the underground is your playground. Dig for treasure, fight huge bosses, build incredible structures, and craft thousands of items in this charming 2D sandbox. With tons of content and endless replayability, Terraria is a true indie legend.', 'Re-Logic', 'Re-Logic', '2011-05-16', ARRAY['Sandbox','Adventure','Indie'], ARRAY['Crafting','2D','Building','Exploration','Boss Fights'], ARRAY['Single-player','Online Co-op','Local Co-op','Controller Support','Cloud Saves'], 'https://upload.wikimedia.org/wikipedia/en/1/1a/Terraria_Steam_artwork.jpg', 'https://upload.wikimedia.org/wikipedia/en/1/1a/Terraria_Steam_artwork.jpg', 83, '$9.99', false);
